import {examples,exampleLabels} from '../data/examples.js';
import {columnLabel,headerHTML,drawHeaders,diffHTML,shapeHTML,drawWidgets} from './dataframe-visuals.js';
import {isNumericColumn} from '../data/semantics.js';
import {WorkerClient} from '../services/worker-client.js';
import {readUpload} from '../services/import.js';
import {t,fmt,getLocale,setLocale,errorText} from '../i18n/locale.js';
import {renderChart,exportChart} from '../charts/render.js';
import {OperationForm} from './operation-form.js';
import {tasks,local,operationInfo,operationLabel,operationTypes} from './operation-catalog.js';
import {drawFeedback} from './preview-feedback.js';
import {esc,$,$$,icon,download,asCSV,localProject} from './utils.js';
const BASE=import.meta.env.BASE_URL;
const CHARTS=['scatter','bar','line','histogram','box','correlation','heatmap','area','distribution','court','missing'];
const AGGS=['mean','sum','median','min','max','std','count','size','nunique'];
const NBA_LABELS={players:['球员名单','Players'],teams:['球队字典','Teams'],games:['比赛赛程','Games'],player_game_stats:['球员逐场统计','Player game statistics'],team_game_stats:['球队逐场统计','Team game statistics'],shots:['逐次投篮','Shots']};
const and=args=>args.length===0?null:args.length===1?args[0]:{op:'and',args};
export class App{
  constructor(root){this.root=root;this.worker=new WorkerClient();this.route='overview';this.snapshot={nodes:[],tables:[]};this.config={x:'pts',y:'ast',category:'player_name',date:'game_date',metric:'pts',aggregate:'mean',correlation:true};this.channels={};this.offset=0;this.pageSize=50;this.tab='dataPreview';this.chartType='scatter';this.nbaTab='playerTab';this.nbaNodes={};this.busyCount=0;this.queryVersion=0;this.draft=null;this.loaded=new Set();this.importData=null;this.form=null;this.lastError=null;this.detailField=null;this.editNode=null;this.previewVersion=0;this.previewTimer=null;this.stepFeedback=null;this.showDiff=false;this.ready=false;this.worker.onRetain=data=>this.ready?localProject('put',{...data,view:this.view()},'navigation').catch(()=>{}):undefined;}
  async start(){try{setLocale(localStorage.getItem('nba-datalab-locale')??'zh-CN');}catch{setLocale('zh-CN');}this.render();
    window.addEventListener('hashchange',()=>this.safe(()=>this.navigate()));
    this.root.onclick=event=>this.click(event);
    this.root.onchange=event=>this.change(event);
    this.root.onpointerover=event=>{const row=event.target.closest('tr[data-row-id]');if(row&&!row.contains(event.relatedTarget))this.highlightRow(row.dataset.rowId);const node=event.target.closest('.pipeline-node');if(node)this.highlightCode(node.querySelector('[data-node]')?.dataset.node);};
    this.root.onpointerout=event=>{const row=event.target.closest('tr[data-row-id]');if(row&&!row.contains(event.relatedTarget))this.highlightRow(null);};
    this.root.onfocusin=event=>{const node=event.target.closest('.pipeline-node');if(node)this.highlightCode(node.querySelector('[data-node]')?.dataset.node);};
    this.root.oninput=event=>{if(event.target.id==='field-search')this.filterFields(event.target.value);};
    this.root.ondragover=event=>{if(event.dataTransfer.types.includes('Files'))event.preventDefault();};
    this.root.ondrop=event=>{event.preventDefault();const file=event.dataTransfer.files[0];if(file)this.safe(()=>this.openImport(file));};
    await this.run(async()=>{const response=await fetch(`${BASE}data/nba/2025-26-nov/manifest.json`);if(!response.ok)throw new Error('LOAD_FAILED');this.manifest=await response.json();await this.loadNBA(['players','teams','games','team_game_stats','player_game_stats']);this.exampleManifest=await (await fetch(`${BASE}data/examples/manifest.json`)).json();this.overview=await this.worker.call('overview');this.playerNames=new Map((await this.worker.call('analysisExport',{id:'source:nba_players',kind:'rows'})).map(r=>[r.player_id,r.player_name]));await this.loadExamples();this.primaryOverview=await this.worker.call('nbaExampleOverview');await this.worker.call('select',{id:'source:example_nba_missing'});this.config={x:'pts',y:'ast',category:'team',metric:'pts',date:'game_date',aggregate:'mean',correlation:true};const query=new URLSearchParams(location.hash.split('?')[1]),requested=query.get('table');if(requested&&!examples[requested]){const nav=await localProject('get',null,'navigation').catch(()=>null);if(nav?.flow.nodes.some(n=>n.id===requested)){await this.worker.call('recover',nav);this.restoreView({...nav.view,locale:getLocale()});}}await this.worker.retain();await this.navigate();this.ready=true;await this.worker.retain();});
  }
  async run(fn){this.busyCount++;this.busy();try{return await fn();}finally{this.busyCount--;this.busy();}}
  safe(fn){return this.run(fn).catch(error=>this.fail(error));}
  busy(){const el=$('#busy');if(el){el.hidden=this.busyCount===0;$('#busy-text').textContent=t('working');}this.root.setAttribute('aria-busy',String(this.busyCount>0));}
  fail(error){if(error.code==='CANCELLED'||error.message==='CANCELLED'){this.toast(errorText({code:'CANCELLED'}));return;}this.lastError=error;this.toast(`${errorText(error)}${error.code||error.message?` (${error.code??error.message})`:''}`,true);console.error('[DataLab]',error.code??error.message,error.details??'');}
  toast(message,error=false){let host=$('#toast');if(!host){host=document.createElement('div');host.id='toast';host.setAttribute('role','status');document.body.append(host);}host.className=error?'toast error':'toast';host.textContent=message;clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>host.classList.remove('toast'),error?10000:4000);}
  name(table){const id=typeof table==='string'?table:table.id;if(id.startsWith('source:example_'))return local(examples[id.slice(15)]?.name??[id,id]);if(id.startsWith('source:nba_'))return NBA_LABELS[id.slice(11)]?.[getLocale()==='zh-CN'?0:1]??id;const node=this.snapshot.nodes?.find(n=>n.id===id);return node?.kind==='operation'?`${id.split(':')[1].padStart(2,'0')} · ${operationLabel(node.spec.type,node.spec.params)}`:(typeof table==='string'?this.snapshot.tables?.find(t=>t.id===id)?.provenance?.fileName:table.provenance?.fileName)??id.replace('source:','');}
  async loadNBA(ids){const missing=ids.filter(id=>!this.loaded.has(id));const texts=await Promise.all(missing.map(async id=>{const meta=this.manifest.tables.find(t=>t.id===id),response=await fetch(`${BASE}data/nba/2025-26-nov/${meta.file}`);if(!response.ok)throw new Error('LOAD_FAILED');const text=await response.text();const bytes=new TextEncoder().encode(text),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('');if(hash!==meta.sha256)throw new Error('SOURCE_MISMATCH');return {id,text,meta};}));
    for(const {id,text,meta}of texts){try{await this.worker.call('import',{text,options:{id:`nba_${id}`,fileName:`NBA · ${id}`,format:'csv',types:Object.fromEntries(meta.columns.map(c=>[c.name,c.type]))}});}catch(error){if(error.code!=='DATASET_EXISTS')throw error;}this.loaded.add(id);}
  }
  async loadExamples(ids=Object.keys(examples)){
    const state=await this.worker.call('snapshot');for(const id of ids){if(state.nodes.some(n=>n.id===`source:example_${id}`))continue;const response=await fetch(`${BASE}data/examples/${id}.csv`);if(!response.ok)throw new Error('LOAD_FAILED');const text=await response.text(),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(n=>n.toString(16).padStart(2,'0')).join('');if(hash!==this.exampleManifest.tables.find(t=>t.id===id)?.sha256)throw new Error('SOURCE_MISMATCH');try{await this.worker.call('import',{text,options:{id:`example_${id}`,format:'csv',fileName:id,labels:exampleLabels(id)}});}catch(error){if(error.code!=='DATASET_EXISTS')throw error;}}
  }
  routeURL(push=false,activeId=this.snapshot.activeId){
    const query=new URLSearchParams();if(this.route==='nba')query.set('tab',this.nbaTab.replace('Tab',''));else if(this.route==='studio'&&activeId)query.set('table',activeId.replace('source:example_',''));
    const url=`#/${this.route}${query.size?'?'+query:''}`;if(location.hash!==url)history[push?'pushState':'replaceState'](null,'',url);
  }
  async navigate(){
    const [path,search='']=location.hash.replace(/^#\/?/,'').split('?'),q=new URLSearchParams(search),route=path||'overview';
    this.route=['overview','nba','studio'].includes(route)?route:({gallery:'studio',workbench:'studio',dashboard:'overview',explore:'nba',cases:'nba'})[route]??'overview';
    this.form=null;this.formFingerprint=null;this.invalidatePreview();
    if(this.route==='nba'){
      const tab=q.get('tab');if(['player','team','trend','court'].includes(tab))this.nbaTab=tab+'Tab';await this.activateNBA();
      if(this.pendingNBASelection){Object.assign(this.channels,this.pendingNBASelection);this.pendingNBASelection=null;await this.analyze();}
    }else if(this.route==='overview')this.render();else{
      const table=q.get('table'),id=examples[table]?`source:example_${table}`:table;
      if(id&&id!==this.snapshot.activeId){const state=await this.worker.call('snapshot');if(state.nodes.some(n=>n.id===id)){await this.worker.call('select',{id});this.channels={};this.draft=null;}}
      await this.analyze();
    }
    this.routeURL();window.scrollTo(0,0);
  }
  goto(route){if(this.route===route)this.safe(()=>this.navigate());else location.hash=`/${route}`;}
  selection(){return and(Object.values(this.channels).filter(Boolean));}
  preserveDraft(){if(this.form)this.draft=this.form.remember();}
  async analyze(){if(this.chartType==='court'){this.config.x='x_legacy';this.config.y='y_legacy';}this.preserveDraft();this.invalidatePreview();const version=++this.queryVersion;const snapshot=await this.worker.call('analyze',{config:{...this.config,correlation:true},selection:this.selection(),offset:this.offset,limit:this.pageSize});if(version!==this.queryVersion)return;this.snapshot=snapshot;if(this.stepFeedback?.key!==snapshot.activeId+':'+snapshot.version)this.stepFeedback=null;if(this.route==='studio')this.routeURL();if(this.chartType==='court'&&!this.canCourt())this.chartType='scatter';this.loaded=new Set(snapshot.nodes.filter(n=>n.kind==='source'&&n.sourceId.startsWith('nba_')).map(n=>n.sourceId.slice(4)));if(snapshot.charts)for(const [key,c]of Object.entries(snapshot.charts.fields))if(c)this.config[key]=c.id;this.render();}
  async mutate(action,payload={}){this.preserveDraft();this.invalidatePreview();await this.worker.call(action,payload);this.channels={};this.offset=0;this.preview=null;await this.worker.retain();await this.analyze();}
  async activateNBA(){await this.loadNBA(this.nbaTab==='courtTab'?['shots']:['teamTab','trendTab'].includes(this.nbaTab)?['team_game_stats']:['player_game_stats']);this.channels={};this.offset=0;this.draft=null;this.editNode=null;
    if(this.nbaTab==='courtTab'){await this.loadNBA(['shots']);await this.worker.call('select',{id:'source:nba_shots'});this.chartType='court';this.config={x:'x_legacy',y:'y_legacy',category:'made',date:'game_date',metric:'shot_distance',aggregate:'mean',correlation:true};}
    else if(['teamTab','trendTab'].includes(this.nbaTab)){await this.worker.call('select',{id:'source:nba_team_game_stats'});this.chartType=this.nbaTab==='trendTab'?'line':'bar';this.config={x:'pts',y:'ast',category:'team_abbr',date:'game_date',metric:'pts',aggregate:'mean',correlation:true};}
    else{await this.worker.call('select',{id:'source:nba_player_game_stats'});this.chartType='scatter';this.config={x:'pts',y:'ast',category:'player_name',date:'game_date',metric:'pts',aggregate:'mean',correlation:true};const state=await this.worker.call('snapshot');if(this.nbaNodes.played&&state.nodes.some(n=>n.id===this.nbaNodes.played&&n.inputs?.[0]==='source:nba_player_game_stats'&&n.spec?.params?.predicate?.field==='played'&&n.spec.params.predicate.value===true))await this.worker.call('select',{id:this.nbaNodes.played});else{const result=await this.worker.call('commit',{spec:{type:'filter',params:{predicate:{op:'eq',field:'played',value:true}}}});this.nbaNodes.played=result.activeId;}}
    await this.analyze();await this.worker.retain();this.nbaValues=await this.worker.call('values',{field:this.nbaTab==='courtTab'?'player_id':this.nbaTab==='playerTab'?'player_name':'team_abbr'});this.render();
  }
  header(){return `<header class="site-header"><a class="brand" href="#/overview" aria-label="${t('brand')}"><span class="brand-ball"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="4" y="5" width="24" height="23" rx="4"/><path d="M4 13h24M12 5v23M20 13v15"/><path d="m7 9 2 0"/></svg></span><span><strong>pandas</strong><small>${t('nbaTheme')}</small></span></a><nav aria-label="${t('component002')}">${['overview','studio','nba'].map((key,i)=>`<a href="#/${key}" class="${this.route===key?'active':''}" ${this.route===key?'aria-current="page"':''}><span class="nav-index">0${i+1}</span>${t(key)}</a>`).join('')}</nav><div class="header-tools"><button class="lang" data-action="locale" aria-label="${t('component003')}">${getLocale()==='zh-CN'?'EN / 中':'ZH / EN'}</button><button class="button primary upload-button" data-action="upload">${icon('upload')}<span>${t('upload')}</span></button></div></header>`;}
  render(){document.title=t('brand');this.form=null;this.root.innerHTML=`${this.header()}<main id="main-content">${this.route==='overview'?this.overviewHTML():this.route==='studio'?this.studioHTML():this.route==='nba'?this.nbaHTML():this.galleryHTML()}</main><footer class="site-footer"><a href="#/overview"><strong>pandas</strong> · ${t('component001')}</a><span>JavaScript · D3.js · ${t('localPrivacy')}</span><button class="text-button" data-action="about">${t('about')} ↗</button></footer><div id="busy" class="busy" hidden role="status"><span class="spinner"></span><span id="busy-text">${t('working')}</span><button data-action="cancel" class="text-button">${t('cancelTask')}</button></div>`;
    this.busy();const step=$('.applied-step');if(step)step.ontoggle=()=>{if(step.open)this.safe(()=>this.loadStepFeedback(this.queryVersion));};if(this.route==='overview')this.drawOverview();else if(this.snapshot.charts){if(this.route==='studio'){this.mountForm();this.drawActiveCharts();this.drawPreview();this.drawStepFeedback();this.drawDataFrame();if(this.showDiff&&!this.preview)this.loadStepFeedback(this.queryVersion).catch(e=>this.fail(e));}else if(this.route==='nba')this.drawActiveCharts();else this.drawGallery();}
  }
  overviewHTML(){const d=this.overview;return `<div class="overview page-shell"><section class="hero pandas-hero"><div class="hero-copy"><span class="eyebrow"><i></i>${t('heroKicker')}</span><h1>${t('heroTitle')}</h1><p>${t('heroText')}</p><div class="hero-actions"><button class="button primary" data-action="go-studio">${t('openStudio')}${icon()}</button><button class="button secondary" data-action="upload">${t('upload')}${icon('upload')}</button></div><div class="hero-proof">${t('component004')}</div><p class="engine-note">${t('jsEngine')}</p><button class="text-button" data-action="go-nba">${t('component005')} ↗</button></div><div class="hero-visual pandas-visual"><div class="visual-heading"><span><i class="dot"></i>${t('component006')}</span><span>pandas ↗</span></div><div class="visual-input"><small>01 / ${t('component007')}</small><div class="mini-data"><span>team</span><span>pts</span>${(this.primaryOverview?.mini??[]).map(r=>`<span>${esc(r.team)}</span><b>${r.pts}</b>`).join('')}</div></div><button class="visual-operation" data-nba-guide="group"><small>02 / ${t('component008')}</small><code>groupby('team')<br>.agg(total=('pts', 'sum'))</code><span>↓</span></button><div class="visual-output"><small>03 / ${t('component009')}</small>${this.heroGroupHTML()}</div><p class="illustration-note">${t('component010')}</p></div></section><section class="visual-layers">${['Operation','Pipeline','Result'].map((key,i)=>`<button class="card" data-operation-start="${['fillna','group','filter'][i]}"><small>0${i+1}</small><h2>${t('visual'+key)}</h2><p>${t('visual'+key+'Hint')}</p><code>${['fillna() · cut() · merge()','DataFrame → DataFrame','describe() · .loc[] · .plot()'][i]}</code></button>`).join('')}</section><section class="capabilities"><div class="section-heading"><div><span class="eyebrow">${t('component011')}</span><h2>${t('component012')}</h2><p>${t('component013')}</p></div></div><div class="capability-grid">${Object.entries(tasks).map(([key,task],i)=>`<button class="capability-card" ${key==='inspect'?'data-action="upload"':`data-operation-start="${operationTypes.find(v=>operationInfo(v).task===key)}"`}><small>0${i+1}</small><strong>${local(task.name)}</strong><code>${task.methods}</code><p>${local(task.intro)}</p><span>↗</span></button>`).join('')}</div></section>${this.nbaExampleHTML()}</div>`;}
  heroGroupHTML(){const buckets=new Map();for(const r of this.primaryOverview?.mini??[]){if(!buckets.has(r.team))buckets.set(r.team,{total:0,n:0});buckets.get(r.team).total+=r.pts;buckets.get(r.team).n++;}const max=Math.max(1,...[...buckets.values()].map(v=>v.total));return [...buckets].map(([key,v])=>`<div><span>${esc(key)}</span><i style="--bar:${v.total/max*100}%"></i><b>${v.total}</b><em>n=${v.n}</em></div>`).join('');}
  nbaExampleHTML(){return `<section class="example-section"><div class="section-heading"><div><span class="eyebrow">${t('guideWorkflow')}</span><h2>${t('nbaPrimaryTitle')}</h2><p>${t('nbaPrimaryHint')}</p></div><button class="button secondary" data-action="add-nba">${t('builtIns')} ↗</button></div><div class="capability-grid nba-guides">${['missing','merge','rolling','group'].map((key,i)=>`<button class="capability-card" data-nba-guide="${key}"><small>0${i+1}</small><strong>${t(key+'Guide')}</strong><p>${t(key+'GuideHint')}</p><code>${({missing:'fillna()',merge:'merge()',rolling:'sort_values() + rolling()',group:'groupby() + agg()'})[key]}</code></button>`).join('')}</div><article class="card trend-card"><div class="section-heading"><div><span class="eyebrow">groupby(game_date) + sum(pts)</span><h2>${t('dataWindow')}</h2><p>${t('nbaDailyHint')}</p></div></div><div id="overview-trend" class="chart-host"></div></article></section>`;}
  drawOverview(){if(!this.primaryOverview)return;renderChart($('#overview-trend'),'area',this.primaryOverview.charts,{locale:getLocale(),title:t('nbaPrimaryTitle'),onSelection:(_channel,predicate)=>this.safe(async()=>{await this.worker.call('select',{id:'source:example_nba_games'});this.config={date:'game_date',metric:'pts',x:'pts',y:'ast',category:'team',aggregate:'sum'};this.chartType='line';this.channels={time:predicate};this.draft=null;this.goto('studio');})});}
  async startNBAGuide(kind){
    await this.worker.call('select',{id:'source:example_nba_missing'});this.channels={};this.offset=0;this.tab='dataPreview';this.chartType='scatter';this.config={x:'pts',y:'ast',category:'team',date:'game_date',metric:'pts',aggregate:'mean'};
    const columns=(await this.worker.call('snapshot')).columns,ref=name=>columns.find(c=>c.name===name).id;
    if(kind==='missing')this.draft={type:'fillna',values:{field:ref('minutes'),method:'median'}};
    if(kind==='merge')this.draft={type:'merge',values:{rightTable:'source:example_nba_teams',left0:ref('team'),right0:'example_nba_teams:c0',how:'left',validate:'many_to_one',suffixLeft:'_x',suffixRight:'_y'}};
    if(kind==='rolling')this.draft={type:'rolling',values:{field:ref('pts'),by:[ref('player_name')],order:ref('game_date'),window:'5',minPeriods:'3',fn:'mean',as:'points_last5'}};
    if(kind==='group')this.draft={type:'group',metricCount:2,values:{keys:[ref('team')],metric0:ref('pts'),fn0:'sum',as0:'points_total',metric1:ref('pts'),fn1:'size',as1:'appearances'}};
    this.autoPreviewNext=true;this.goto('studio');
  }
  intro(title,text,actions=''){return `<div class="page-intro"><div><span class="eyebrow">pandas / ${t(this.route)}</span><h1>${t(title)}</h1><p>${t(text)}</p></div>${actions}</div>`;}
  selectionHTML(){const selection=this.selection();return `<div class="selection-strip ${selection?'has-selection':''}" title="${esc(selection?this.predicateLabel(selection):'')}"><span>${icon('filter')} ${selection?`${t('selected')} <strong>${fmt(this.snapshot.rows,0)} / ${fmt(this.snapshot.committedRows,0)}</strong> · ${t('selectionPending')} <span class="selection-chips">${Object.entries(this.channels).filter(([,v])=>v).map(([key,value])=>`<button class="selection-chip" data-clear-channel="${key}" title="${esc(this.predicateLabel(value))}">${esc(this.predicateLabel(value))} ×</button>`).join('')}</span>`:t('selectionHint')}</span><div><button class="text-button" data-action="clear-selection" ${selection?'':'disabled'}>${t('clearSelection')}</button><button class="button small primary" data-action="apply-selection" ${selection?'':'disabled'}>${t('applySelection')}</button></div></div>`;}
  datasetPanel(){const tables=this.snapshot.tables??[],cols=this.snapshot.columns??[];return `<aside class="data-sidebar"><div class="pane-heading"><h2>${icon('database')}${t('data')}</h2><button class="icon-button" data-action="upload" aria-label="${t('upload')}">+</button></div><p class="inspect-methods">${t('inspectMethods')}<br><code>shape · dtypes · isna() · value_counts()</code></p><div class="dataset-list">${tables.filter(table=>!table.id.startsWith('source:nba_')||table.id===this.snapshot.activeId).map(table=>`<div class="dataset-item ${table.id===this.snapshot.activeId?'active':''}"><button data-node="${esc(table.id)}" title="${esc(table.provenance?.fileName??table.id)}">${icon(table.id.startsWith('source:')?'database':'chart')}<span>${esc(this.name(table))}<small>${fmt(table.rows,0)} ${t('rows')}</small></span></button>${table.id.startsWith('source:')?`<button class="remove-dataset" data-remove-source="${esc(table.id.slice(7))}" aria-label="${t('remove')}">×</button>`:''}</div>`).join('')}</div><button class="text-button add-nba" data-action="add-nba">+ ${t('addNBA')}</button><div class="field-heading"><h3>${t('fields')} <span>${cols.length}</span></h3><input type="search" id="field-search" placeholder="${t('searchFields')}" aria-label="${t('searchFields')}"></div><div class="fields-list">${cols.map(c=>`<div class="field-entry"><button class="field-item" data-field="${esc(c.id)}" data-name="${esc((c.name+' '+columnLabel(c)).toLowerCase())}"><span class="type-icon">${isNumericColumn(c)?'#':['date','datetime'].includes(c.type)?'◷':c.type==='boolean'?'◐':'Aa'}</span><span>${esc(columnLabel(c))}<small>${esc(c.name)}</small></span></button><button class="field-type-button" data-change-type="${esc(c.id)}" title="${t('changeType')}">${c.semantic==='key'?t('keyRole'):esc(c.type)}</button></div>`).join('')}</div><div class="privacy-note">${icon('check')}<span>${t('localPrivacy')}<small>50 MiB · 100k ${t('rows')} · 200 ${t('columns')}</small></span></div></aside>`;}
  statsHTML(){const s=this.snapshot,missing=s.profile?.columns.reduce((n,c)=>n+c.missing,0);return `<div class="work-stats">${[[s.rows,'rows'],[s.columns?.length,'columns'],[missing,'missing']].map(([v,key])=>`<div><small>${t(key)}</small><strong>${fmt(v,0)}</strong></div>`).join('')}${s.charts?.shots&&this.activeSources().some(v=>v.sourceId==='nba_shots')?`<div><small>${t('fieldGoal')}</small><strong>${fmt(s.charts.shots.pct===null?null:s.charts.shots.pct*100,1)}<em>%</em></strong><span>${fmt(s.charts.shots.made,0)} / ${fmt(s.charts.shots.attempts,0)}</span></div>`:`<div><small>${t('quality')}</small><strong>${s.rows&&s.columns?.length?fmt(100*(1-missing/(s.rows*s.columns.length)),1):'—'}<em>%</em></strong><span>${t('component016')}</span></div>`}</div>`;}
  options(columns,value,blank=false){return `${blank?'<option value="">—</option>':''}${columns.map(c=>`<option value="${esc(c.id)}" ${c.id===value||c.name===value?'selected':''}>${esc(columnLabel(c))} · ${esc(c.name)}</option>`).join('')}`;}
  encodings(){const cols=this.snapshot.columns??[],num=cols.filter(c=>isNumericColumn(c)),dates=cols.filter(c=>['date','datetime'].includes(c.type));return `<details class="encodings"><summary>${t('chartSettings')}<span>＋</span></summary><div class="encoding-grid">${this.chartType==='court'?`<label>${t('component017')}<select data-config="courtMode">${[['points',t('component018')],['frequency',t('component019')],['rate',t('component020')]].map(([v,label])=>`<option value="${v}" ${v===(this.config.courtMode??'points')?'selected':''}>${label}</option>`).join('')}</select></label>`:''}${[['x','xField',num],['y','yField',num],['category','category',cols],['date','date',dates],['metric','metric',num]].map(([key,label,columns])=>`<label>${t(label)}<select data-config="${key}" ${this.chartType==='court'&&['x','y'].includes(key)?'disabled':''}>${this.options(columns,this.config[key],key==='date')}</select></label>`).join('')}<label>${t('aggregate')}<select data-config="aggregate">${AGGS.map(fn=>`<option value="${fn}" ${fn===this.config.aggregate?'selected':''}>${t(fn)}</option>`).join('')}</select></label><label>${t('bins')}<input type="number" min="4" max="60" data-config="bins" value="${this.config.bins??20}"></label><label>${t('correlation')}<select data-config="corrFields" multiple aria-label="${t('correlation')}">${num.map(c=>`<option value="${esc(c.id)}" ${(this.config.corrFields??num.slice(0,8).map(c=>c.id)).includes(c.id)?'selected':''}>${esc(columnLabel(c))} · ${esc(c.name)}</option>`).join('')}</select></label></div></details>`;}
  canvasHTML(){return `<article class="card analysis-card"><div class="canvas-heading"><div><span class="eyebrow">${t('component021')}</span><h2>.plot() · ${t('chart')}</h2><button class="text-button" data-action="chart-gallery">${t('galleryInStudio')} ↗</button></div><select id="chart-type" aria-label="${t('chartType')}">${CHARTS.map(type=>`<option value="${type}" ${type===this.chartType?'selected':''} ${!this.chartAvailable(type)?'disabled':''}>${t(type==='missing'?'missingChart':type)}</option>`).join('')}</select></div>${this.encodings()}${this.snapshot.charts?.grain?`<p class="hint group-grain-note">${t('component022')}</p>`:''}${this.chartAvailable(this.chartType)?'':`<p class="inline-error">${this.chartRequirement(this.chartType)}</p>`}<div class="main-chart chart-host" id="main-chart"></div><div class="chart-footnote"><span>${this.snapshot.charts?.pointSample&&(this.chartType==='scatter'||(this.chartType==='court'&&(this.config.courtMode??'points')==='points'))?t('sampleHint'):t('allDataHint')}</span><span class="narrow-chart-note">${t('component023')}</span><button class="text-button" data-action="chart-svg">SVG ↓</button><button class="text-button" data-action="chart-png">PNG ↓</button></div>${this.chartType==='court'?`<p class="coordinate-note">${t('coordinateNote')} ${t('fullRange')} · ${t('lowN')}</p>`:''}</article><details class="card distribution-card"><summary>${t('distribution')}</summary><div class="canvas-heading"><h3>${t('distribution')}<span class="muted"> / ${esc(this.snapshot.charts?.fields.x?.name??'')}</span></h3><span class="hint">${t('chartHint')}</span></div><div class="chart-host compact-chart" id="secondary-chart"></div></details>`;}
  tableHTML(records=this.snapshot.records,columns=this.snapshot.columns,sortable=true){if(!columns?.length)return `<p class="empty-state">${t('noDataset')}</p>`;return `<div class="table-scroll"><table><thead><tr><th class="row-number">#</th>${columns.map(c=>`<th>${sortable?`<button data-sort="${esc(c.id)}">${esc(columnLabel(c))} <span>↕</span></button>`:esc(c.name)}<small>${c.semantic==='key'?t('keyRole'):esc(c.type)}${c.label?` · ${esc(c.name)}`:''}</small>${sortable?headerHTML(c,this.snapshot.profile?.columns.find(p=>p.id===c.id)):''}</th>`).join('')}</tr></thead><tbody>${records?.length?records.map((r,i)=>`<tr data-row-id="${esc(sortable?(this.snapshot.rowIds?.[i]??''):'')}"><td class="row-number">${(sortable?this.offset:0)+i+1}</td>${columns.map(c=>`<td class="${r[c.name]===null?'null':typeof r[c.name]==='number'?'numeric':''}" title="${esc(r[c.name]??t('na'))}">${r[c.name]===null?`<span>${t('na')}</span>`:esc(typeof r[c.name]==='number'?fmt(r[c.name],5):r[c.name])}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${columns.length+1}"><div class="empty-state"><strong>${t('empty')}</strong><p>${t('emptyHint')}</p></div></td></tr>`}</tbody></table></div>`;}
  profileHTML(){return `<div class="profile-summary"><p class="hint">${t('allDataHint')} · std(ddof=1) · quantile(linear)</p><div class="table-scroll"><table><thead><tr>${['field','type','valid','missing','missingRate','unique','mean','std','min','q1','median','q3','max'].map(key=>`<th>${t(key)}</th>`).join('')}</tr></thead><tbody>${this.snapshot.profile?.columns.map(c=>`<tr><th><button class="text-button" data-field="${esc(c.id)}">${esc(c.name)}</button></th><td>${c.type}</td>${['count','missing','missingRate','unique','mean','std','min','q1','median','q3','max'].map(k=>`<td class="numeric">${k==='missingRate'?fmt(c[k]===null?null:c[k]*100,1)+'%':fmt(c[k],3)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
  resultsHTML(){const s=this.snapshot;return `<article class="card result-card"><div class="dataframe-heading"><h2>DataFrame <small>${this.snapshot.rows} × ${this.snapshot.columns?.length??0}</small></h2><label class="check"><input type="checkbox" id="show-diff" ${this.showDiff?'checked':''}>${t('diff')}</label></div><p class="hint grid-hint">${t('headerHint')} ${t('rowHover')} ${this.selection()?`${t('matchedRows')}: ${s.rows}`:''}</p><div id="dataframe-diff">${this.showDiff?diffHTML(this.preview?.diff??(this.stepFeedback?.id===s.activeId?this.stepFeedback.data.diff:null)):''}</div><div class="result-tabs" role="tablist">${['dataPreview','statistics','pandas'].map(tab=>`<button role="tab" aria-selected="${this.tab===tab}" class="${this.tab===tab?'active':''}" data-tab="${tab}">${t(tab)}</button>`).join('')}<span class="result-version">v${s.version??0} · ${t('allDataHint')}</span></div>${this.tab==='dataPreview'?`${this.tableHTML()}<div class="pagination"><span>${t('showing')} ${s.rows?this.offset+1:0}–${Math.min(this.offset+this.pageSize,s.rows??0)} / ${fmt(s.rows,0)}</span><div><label>${t('perPage')}<select id="page-size">${[20,50,100].map(n=>`<option ${n===this.pageSize?'selected':''}>${n}</option>`).join('')}</select></label><button class="text-button" data-action="head">${t('head')}</button><button class="text-button" data-action="tail">${t('tail')}</button><button class="button small secondary" data-action="prev-page" ${this.offset?'':'disabled'} aria-label="${t('previous')}">←</button><button class="button small secondary" data-action="next-page" ${this.offset+this.pageSize<s.rows?'':'disabled'} aria-label="${t('next')}">→</button></div></div>`:this.tab==='statistics'?this.profileHTML():`<div class="code-view"><strong>${t('appliedStep')} · ${fmt(s.committedRows,0)} ${t('rows')}</strong><p>${t('codeNote')}</p><p class="hint">${t('jsEngine')} ${this.selection()?t('selectionPending'):''}</p><pre><code>${esc(s.pandas?.code??t('sourceCode'))}</code></pre><button class="button secondary small" data-export="python">${t('python')}${icon('download')}</button></div>`}</article>`;}
  pipelineHTML(){const all=this.snapshot.nodes??[],path=new Set(),visit=id=>{if(path.has(id))return;path.add(id);all.find(n=>n.id===id)?.inputs?.forEach(visit);};visit(this.snapshot.activeId);const nodes=all.filter(n=>path.has(n.id));return `<section class="card pipeline-card"><div class="canvas-heading"><div><span class="eyebrow">${t('component024')}</span><h2>${t('pipeline')}</h2></div><div><button class="icon-button" data-action="undo" ${this.snapshot.history?.canUndo?'':'disabled'} title="${t('undo')}">↶</button><button class="icon-button" data-action="redo" ${this.snapshot.history?.canRedo?'':'disabled'} title="${t('redo')}">↷</button></div></div><div class="pipeline-nodes">${nodes.map(n=>`<div class="pipeline-node ${this.snapshot.activeId===n.id?'active':''}"><button data-node="${esc(n.id)}"><small>${n.kind==='source'?t('original'):n.inputs.join(' + ')} →</small><strong>${esc(this.name(n.id))}</strong>${(()=>{const table=this.snapshot.tables.find(t=>t.id===n.id),r=this.snapshot.steps?.find(s=>s.id===n.id)?.report,a={rows:table?.rows??0,columns:table?.columns.length??0};return shapeHTML(r?.before??a,r?.after??a);})()}</button>${n.kind==='operation'?`<div><button class="text-button" data-edit="${esc(n.id)}">${t('edit')}</button><button class="text-button" data-delete-node="${esc(n.id)}">${t('remove')}</button>${['group','pivot_table','pivot'].includes(n.spec.type)?`<button class="text-button" data-drill="${esc(n.id)}">${t('component025')}</button>`:''}</div>`:''}</div>`).join('')}</div>${this.activeStepHTML()}</section>`;}
  studioHTML(){return `<div class="studio page-shell wide">${this.intro('studioTitle','studioText',this.exportMenu())}${this.pipelineHTML()}<div class="workspace">${this.datasetPanel()}<div class="work-main">${this.selectionHTML()}${this.statsHTML()}<p class="dataset-note hint">${this.activeSources().filter(s=>s.sourceId.startsWith('example_')).map(s=>local(examples[s.sourceId.slice(8)]?.note??['',''])).join(' · ')}</p>${this.activeSources().some(s=>s.sourceId==='example_nba_missing')?`<div class="practice-banner"><strong>${t('practiceData')}</strong><button class="text-button" data-original-data="true">${t('originalData')} ↗</button><button class="text-button" data-audit-data="true">${t('auditData')} ↓</button></div>`:''}<p class="scope-note">${t('appliedScope')}</p>${this.snapshot.activeId?`${this.resultsHTML()}<section id="operation-preview" aria-live="polite">${this.previewHTML()}</section><div class="plot-code-layout"><section>${this.canvasHTML()}</section>${this.liveCodeHTML()}</div>`: `<article class="card empty-state"><h2>${t('noDataset')}</h2><button class="button primary" data-action="upload">${t('upload')}</button><button class="button secondary" data-action="add-nba">${t('loadExample')}</button></article>`}</div><aside class="operation-sidebar card"><div class="pane-heading"><h2>${icon('filter')}${t('operation')}</h2><span class="pill">23 + IQR</span></div><p class="hint">${t('previewHint')}</p><div id="operation-form"></div><div id="operation-widgets" class="operation-widgets"></div><button class="button primary full" data-action="preview" ${this.snapshot.activeId?'':'disabled'}>${t('preview')}${icon()}</button><div id="operation-code">${this.operationCodeHTML()}</div><p class="engine-note">${t('jsEngine')}</p></aside></div></div>`;}
  liveCodeHTML(){
    const ids=new Set(),visit=id=>{if(ids.has(id))return;ids.add(id);this.snapshot.nodes.find(n=>n.id===id)?.inputs?.forEach(visit);};visit(this.snapshot.activeId);
    return `<article class="card live-code"><h2>${t('liveCode')}</h2><p class="hint">${t('jsEngine')}</p><div id="live-code-steps">${(this.snapshot.steps??[]).filter(s=>ids.has(s.id)&&s.code).map(s=>`<section data-code-node="${s.id}" class="${s.id===this.snapshot.activeId?'code-active':''}"><small>${esc(this.name(s.id))} · ${t('appliedCode')}</small><pre><code>${esc(s.code)}</code></pre></section>`).join('')||`<pre><code>df = pd.read_csv(...)</code></pre>`}</div><div id="live-preview-code">${this.livePreviewHTML()}</div><button class="text-button" data-export="python">${t('python')} ↓</button></article>`;
  }
  livePreviewHTML(){return this.preview?`<section class="code-pending"><small>${t('pendingPreview')}</small><pre><code>${esc(this.preview.pandas?.code??'')}</code></pre></section>`:'';}
  updateLiveCode(){const host=$('#live-preview-code');if(host)host.innerHTML=this.livePreviewHTML();}
  highlightCode(id){$$('[data-code-node]').forEach(el=>el.classList.toggle('code-active',el.dataset.codeNode===id));}
  updateDiff(){const host=$('#dataframe-diff');if(host)host.innerHTML=this.showDiff?diffHTML(this.preview?.diff??(this.stepFeedback?.id===this.snapshot.activeId?this.stepFeedback.data.diff:null)):'';}
  drawDataFrame(){drawHeaders(this.root,this.snapshot.columns??[],this.snapshot.profile?.columns??[],(channel,predicate)=>this.safe(async()=>{this.channels[channel]=predicate;this.offset=0;await this.analyze();}));}
  drawOperationWidgets(){drawWidgets($('#operation-widgets'),this.form,this.snapshot.profile?.columns??[],this.preview,()=>{this.drawOperationWidgets();this.schedulePreview();});}
  highlightRow(id){
    const chart=$('#main-chart');if(!chart)return;const row=this.snapshot.records?.[this.snapshot.rowIds?.indexOf(id)],data=this.snapshot.charts;
    $$('[data-row-id]',chart).forEach(el=>el.classList.toggle('row-highlight',!!id&&el.dataset.rowId===id));
    if(this.chartType==='bar')$$('.bar-row',chart).forEach(el=>{const key=el.__data__?.key,c=data?.fields.category;el.classList.toggle('row-highlight',!!row&&!!c&&row[c.name]===key);});
    chart.querySelector('.row-locator')?.remove();
    if(row&&['scatter','court'].includes(this.chartType)&&!chart.querySelector(`[data-row-id="${CSS.escape(id)}"]`)){
      // The chart exposes its actual scales, including the court aspect ratio.
      const svg=chart.querySelector('svg'),scale=svg?.__rowScales,x=row[data.fields.x?.name],y=row[data.fields.y?.name];
      if(scale&&typeof x==='number'&&typeof y==='number'){const dot=document.createElementNS('http://www.w3.org/2000/svg','circle');dot.setAttribute('class','row-locator');dot.setAttribute('cx',scale.x(x));dot.setAttribute('cy',scale.y(y));dot.setAttribute('r','8');dot.setAttribute('fill','none');dot.setAttribute('stroke','#a35f25');dot.setAttribute('stroke-width','3');svg.append(dot);}
    }
  }
  typeDialog(ref){const c=this.snapshot.columns.find(c=>c.id===ref);if(!c)return;this.dialog(t('changeType'),`<p>${esc(columnLabel(c))} · <code>${esc(c.name)}</code></p><p class="hint">${t('roleNote')}</p><label>${t('type')}<select id="semantic-type">${['key','string','integer','number','date','datetime','boolean'].map(type=>`<option value="${type}" ${type===(c.semantic==='key'?'key':c.type)?'selected':''}>${type==='key'?t('keyRole'):type}</option>`).join('')}</select></label><button class="button primary" id="apply-type">${t('typeCommit')}</button>`,dialog=>$('#apply-type',dialog).onclick=()=>this.safe(async()=>{if(this.selection())throw new Error('SELECT_FIRST');const type=$('#semantic-type',dialog).value;await this.mutate('commit',{spec:{type:'cast',params:{field:ref,type:type==='key'?c.type:type,semantic:type==='key'?'key':'value',errors:'raise'}}});dialog.close();}));}
  galleryDialog(){this.dialog(t('galleryInStudio'),`<div class="chart-gallery-choices">${CHARTS.map(type=>`<button class="source-choice" data-chart-choice="${type}" ${this.chartAvailable(type)?'':'disabled'}><span>${t(type==='missing'?'missingChart':type)}<small>${this.chartRequirement(type)}</small></span>↗</button>`).join('')}</div>`,dialog=>$$('[data-chart-choice]',dialog).forEach(el=>el.onclick=()=>{this.chartType=el.dataset.chartChoice;this.preserveDraft();dialog.close();this.render();}));}
  exportMenu(){return `<details class="export-menu"><summary class="button secondary">${icon('download')}${t('export')}<span>⌄</span></summary><div class="export-options">${['csv','selectionCSV','resultJSON','resultCSV','flow','project','python','svg','png'].map(k=>`<button data-export="${k}" ${k==='selectionCSV'&&!this.selection()?'disabled':''}>${t(k)}</button>`).join('')}<hr><button data-action="restore-flow">${t('restoreFlow')}</button><button data-action="save-local">${t('saveSession')}</button><button data-action="restore-local">${t('restoreSession')}</button><button data-action="clear-local">${t('clearLocal')}</button></div></details>`;}
  mountForm(){if(!this.snapshot.activeId)return;this.form=new OperationForm($('#operation-form'),{columns:this.snapshot.columns,tables:[...(this.snapshot.tables??[])].sort((a,b)=>Number(b.id.startsWith('source:example_'))-Number(a.id.startsWith('source:example_'))).map(table=>({...table,displayName:this.name(table)})),activeId:this.snapshot.activeId,draft:this.draft,charts:ref=>{const col=this.snapshot.profile.columns.find(c=>c.id===ref);return col&&col.q1!==null?{low:col.q1-1.5*(col.q3-col.q1),high:col.q3+1.5*(col.q3-col.q1)}:null;},onChange:()=>{this.drawOperationWidgets();this.schedulePreview();}});this.drawOperationWidgets();if(this.autoPreviewNext){this.autoPreviewNext=false;this.schedulePreview();}}
  previewHTML(){if(!this.preview)return '';const p=this.preview,r=p.report;return `<article class="card preview-result"><div class="canvas-heading"><div><span class="eyebrow">${t('pendingPreview')}</span><h2>${esc(operationLabel(p.spec.type,p.spec.params))}</h2></div><button class="button primary" data-action="commit">${t('apply')}${icon('check')}</button></div><p class="hint">${t('jsEngine')}</p><div class="preview-numbers">${['rows','columns','missing'].map(key=>`<div><small>${t(key)}</small><span>${fmt(r.before[key],0)} → <strong>${fmt(r.after[key],0)}</strong></span></div>`).join('')}${r.invalidRows?`<div><small>${t('invalid')}</small><span>${r.invalidRows.length}</span></div>`:''}</div>${r.edges?`<p class="hint">${t('edges')}: ${r.edges.map(v=>fmt(v,5)).join(' / ')}</p>`:''}<div class="preview-graphs" data-operation-feedback></div><details><summary>${t('dataPreview')} (${Math.min(8,p.rows)} / ${p.rows})</summary>${this.tableHTML(p.records,p.columns,false)}</details><details><summary>${t('parametersAndLimits')}</summary><pre>${esc(JSON.stringify(p.spec.params,null,2))}</pre></details></article>`;}
  drawActiveCharts(){const data=this.snapshot.charts;if(!data)return;const handlers={locale:getLocale(),title:t(this.chartType),courtMode:this.config.courtMode??'points',onSelection:(channel,predicate)=>this.safe(async()=>{this.channels[channel]=predicate;this.offset=0;await this.analyze();}),onPair:(x,y)=>this.safe(async()=>{this.config.x=x;this.config.y=y;this.chartType='scatter';await this.analyze();}),onField:ref=>{if(this.route==='nba'){this.goto('studio');return;}this.configureMissing(ref);}};
    if($('#main-chart')&&this.chartAvailable(this.chartType))renderChart($('#main-chart'),this.chartType,data,handlers);if($('#secondary-chart'))renderChart($('#secondary-chart'),'histogram',data,{...handlers,title:t('distribution')});
  }
  nbaHTML(){const court=this.nbaTab==='courtTab',player=this.nbaTab==='playerTab';return `<div class="nba page-shell">${this.intro('exploreTitle','exploreText',`<button class="button primary" data-action="send-studio">${t('sendStudio')}${icon()}</button>`)}<div class="explore-tabs">${['playerTab','teamTab','trendTab','courtTab'].map((tab,i)=>`<button data-nba-tab="${tab}" class="${tab===this.nbaTab?'active':''}"><span>0${i+1}</span>${t(tab)}</button>`).join('')}<span>${t('dataWindow')}</span></div><div class="nba-controls card"><label>${t(player||court?'choosePlayer':'chooseTeam')}<select id="nba-entity"><option value="">${t(player||court?'allPlayers':'allTeams')}</option>${(this.nbaValues??[]).filter(v=>v.value!==null).sort((a,b)=>String(a.value).localeCompare(String(b.value))).map(v=>`<option value="${esc(v.value)}" ${this.channels.entity?.value===v.value?'selected':''}>${esc(court?this.playerNames?.get(v.value)??v.value:v.value)}</option>`).join('')}</select></label><label>${t('metric')}<select id="nba-metric">${(court?['shot_distance','shot_value']:['pts','ast','reb','stl','blk','tov','fg_pct']).map(v=>`<option ${v===this.config.metric?'selected':''}>${v}</option>`).join('')}</select></label>${!court?`<label>${t('aggregate')}<select data-config="aggregate">${['mean','sum','max','std'].map(fn=>`<option value="${fn}" ${fn===this.config.aggregate?'selected':''}>${t(fn)}</option>`).join('')}</select></label>`:''}<div class="nba-scope"><i class="dot"></i>${player?t('actualPlayed'):t('snapshotNote')}</div></div>${this.selectionHTML()}${this.statsHTML()}<div class="nba-chart-layout"><div>${this.canvasHTML()}</div><aside class="card nba-notebook"><span class="eyebrow">${t('component026')}</span><h2>${t('component027')}</h2><p>${court?t('coordinateNote'):player?t('component028'):t('component029')}</p><div class="notebook-divider"></div><span class="label">${t('scope')}</span><strong>${t('component030')}</strong><p>${t('snapshotNote')}</p>${court?`<div class="notebook-divider"></div><span class="label">${t('attempts')} / ${t('made')}</span><strong>${fmt(this.snapshot.charts?.shots?.attempts,0)} / ${fmt(this.snapshot.charts?.shots?.made,0)}</strong><p>${t('lowN')}</p>`:''}<button class="button secondary full" data-action="about">${t('dataLimits')}↗</button></aside></div>${this.resultsHTML()}</div>`;}
  galleryHTML(){return `<div class="gallery page-shell">${this.intro('galleryTitle','galleryText',`<button class="button secondary" data-action="go-studio">${t('openStudio')}${icon()}</button>`)}<div class="gallery-data card"><span>${icon('database')} ${t('currentData')} <strong>${esc(this.snapshot.activeId?this.name(this.snapshot.activeId):'—')}</strong></span><span>${fmt(this.snapshot.rows,0)} ${t('rows')} · ${t('allDataHint')}</span></div><div class="gallery-encodings card">${this.encodings()}</div><div class="gallery-grid">${CHARTS.map((type,i)=>`<article class="card gallery-card"><div class="canvas-heading"><div><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${t('component031')}</span><h2>${t(type==='missing'?'missingChart':type)}</h2></div><span class="chart-number">↗</span></div><div class="chart-host gallery-chart" id="gallery-${type}"></div><p class="hint">${t(({scatter:'numericTwo',bar:'categoryAny',line:'dateNumeric',histogram:'numericOne',box:'numericOne',correlation:'numericMany',heatmap:'requiresPivot',area:'dateNumeric',distribution:'numericOne',court:'requiresShots',missing:'anyTable'})[type])}</p><button class="button secondary full" data-use-chart="${type}" ${!this.chartAvailable(type)?'disabled':''}>${t('useChart')}${icon()}</button></article>`).join('')}</div></div>`;}
  drawGallery(){for(const type of CHARTS){if(!this.chartAvailable(type)){$(`#gallery-${type}`).innerHTML=`<p class="empty-state">${this.chartRequirement(type)}</p>`;continue;}renderChart($(`#gallery-${type}`),type,this.snapshot.charts,{locale:getLocale(),title:t(type==='missing'?'missingChart':type)});}}
  invalidatePreview(){clearTimeout(this.previewTimer);this.previewVersion++;this.preview=null;this.pendingOperation=null;}
  operationCodeHTML(){return this.preview?`<details class="equivalent-code"><summary>${t('equivalentCode')} · ${t('pendingPreview')}</summary><p class="hint">${t('previewCodeNote')}</p><pre><code>${esc(this.preview.pandas?.code??'')}</code></pre></details>`:`<p class="preview-status hint">${t('previewInvalid')}</p>`;}
  schedulePreview(){const draft=this.form?.remember()??this.draft,fingerprint=JSON.stringify(draft);if(fingerprint===this.formFingerprint)return;this.formFingerprint=fingerprint;this.invalidatePreview();this.draft=draft;this.updateDiff();this.updateLiveCode();const host=$('#operation-preview');if(host)host.innerHTML='';const code=$('#operation-code');if(code)code.innerHTML=`<p class="preview-status hint">${t('previewComputing')}</p>`;this.previewTimer=setTimeout(()=>this.requestPreview(true).catch(error=>this.fail(error)),550);}
  async requestPreview(automatic=false){if(!this.form||this.route!=='studio')return;if(this.selection()){if(!automatic)this.toast(t('applyFirst'),true);const code=$('#operation-code');if(code)code.innerHTML=`<p class="hint">${t('applyFirst')}</p>`;return;}clearTimeout(this.previewTimer);const version=++this.previewVersion,active=this.snapshot.activeId;let operation;try{operation=this.form.read();const preview=await this.worker.call('preview',operation);if(version!==this.previewVersion||active!==this.snapshot.activeId||this.route!=='studio')return;this.pendingOperation=operation;this.preview=preview;this.showDiff=true;const toggle=$('#show-diff');if(toggle)toggle.checked=true;this.updateDiff();this.updateLiveCode();this.drawOperationWidgets();$('#operation-preview').innerHTML=this.previewHTML();$('#operation-code').innerHTML=this.operationCodeHTML();this.drawPreview();if(!automatic)$('#operation-preview').scrollIntoView({block:'start',behavior:'smooth'});}catch(error){if(version!==this.previewVersion)return;this.preview=null;this.pendingOperation=null;const host=$('#operation-code');if(host)host.innerHTML=`<p class="inline-error" role="status">${esc(errorText(error))}</p>`;if(!automatic)throw error;}}
  configureMissing(ref){if(this.route!=='studio'){this.draft={type:'fillna',values:{field:ref}};this.goto('studio');return;}this.form.type=['fillna','dropna'].includes(this.form.type)?this.form.type:'fillna';this.form.saved=null;this.form.draw();if(this.form.type==='dropna'){const box=$('[name=subset]',this.form.host).find(el=>el.value===ref);if(box)box.checked=true;}else this.form.setField(ref);this.schedulePreview();this.form.host.scrollIntoView({block:'center',behavior:'smooth'});}
  chartAvailable(type){const cols=this.snapshot.columns??[],num=cols.filter(c=>isNumericColumn(c)).length,date=cols.some(c=>['date','datetime'].includes(c.type));if(type==='court')return this.canCourt();if(['scatter','correlation'].includes(type))return num>=2;if(['histogram','distribution','box'].includes(type))return num>=1;if(['line','area'].includes(type))return num>=1&&date;if(type==='heatmap')return Boolean(this.snapshot.charts?.pivotHeat?.length)||num>=2;return cols.length>0;}
  chartRequirement(type){return t(({scatter:'numericTwo',correlation:'numericTwo',line:'dateNumeric',area:'dateNumeric',histogram:'numericOne',distribution:'numericOne',box:'numericOne',heatmap:'requiresPivot',court:'requiresShots',missing:'anyTable',bar:'categoryAny'})[type]);}
  activeStepHTML(){const node=this.snapshot.nodes?.find(n=>n.id===this.snapshot.activeId);if(node?.kind!=='operation')return '';const info=operationInfo(node.spec.type,node.spec.params),r=this.snapshot.result;return `<details class="applied-step"><summary>${t('appliedStep')} · ${esc(operationLabel(node.spec.type,node.spec.params))}</summary><p>${esc(info.meaning)}</p><p class="hint">${esc(info.parameters)} ${esc(info.limit)}</p><p class="hint">${t('before')}: ${node.inputs.map(id=>esc(this.name(id))).join(' + ')} → ${t('after')}: ${esc(this.name(node.id))}</p>${r?`<div class="preview-numbers">${['rows','columns','missing'].map(k=>`<div><small>${t(k)}</small><span>${r.before[k]} → <strong>${r.after[k]}</strong></span></div>`).join('')}</div>`:''}<div id="applied-feedback"></div><details><summary>${t('parametersAndLimits')}</summary><pre>${esc(JSON.stringify(node.spec.params,null,2))}</pre></details><details><summary>${t('equivalentCode')} · ${t('appliedStep')}</summary><pre>${esc(this.snapshot.pandas?.code??'')}</pre></details></details>`;}
  async loadStepFeedback(version){const node=this.snapshot.nodes?.find(n=>n.id===this.snapshot.activeId);if(this.route!=='studio'||node?.kind!=='operation')return;const key=node.id+':'+this.snapshot.version;if(this.stepFeedback?.key!==key){const data=await this.worker.call('preview',{spec:node.spec,inputs:node.inputs});if(version!==this.queryVersion)return;this.stepFeedback={key,data,id:node.id};}this.drawStepFeedback();this.updateDiff();}
  drawStepFeedback(){if(this.stepFeedback?.id===this.snapshot.activeId&&this.stepFeedback.key===this.snapshot.activeId+':'+this.snapshot.version)drawFeedback($('#applied-feedback'),this.stepFeedback.data,{onField:ref=>this.configureMissing(ref)});}
  filterFields(value){$$('[data-field][data-name]').forEach(el=>(el.closest('.field-entry')??el).hidden=!el.dataset.name.includes(value.toLowerCase()));}
  view(){return {config:this.config,chartType:this.chartType,channels:this.channels,tab:this.tab,locale:getLocale(),pageSize:this.pageSize};}
  activeSources(){const nodes=new Map((this.snapshot.nodes??[]).map(n=>[n.id,n])),sources=[],seen=new Set();const visit=id=>{if(seen.has(id))return;seen.add(id);const node=nodes.get(id);if(node?.kind==='source')sources.push({sourceId:node.sourceId,fileName:this.snapshot.tables?.find(t=>t.id===id)?.provenance?.fileName??node.sourceId});else for(const input of node?.inputs??[])visit(input);};visit(this.snapshot.activeId);return sources;}
  canCourt(){const cols=this.snapshot.columns??[];return ['x_legacy','y_legacy'].every(name=>cols.some(c=>c.name===name&&isNumericColumn(c)))&&cols.some(c=>c.name==='made'&&c.type==='boolean')&&this.activeSources().some(s=>s.sourceId==='nba_shots');}
  sourceCaption(){const sources=this.activeSources(),nba=sources.some(s=>s.sourceId.startsWith('nba_')),names=sources.filter(s=>!s.sourceId.startsWith('nba_')).map(s=>s.sourceId.startsWith('example_')?local(examples[s.sourceId.slice(8)]?.name??[s.fileName,s.fileName]):s.fileName).join(' + ');return `${nba?'SportsDataverse / NBA · '+t('component032'):''}${nba&&names?' + ':''}${names}${this.chartType==='court'?t('component033'):''}`.slice(0,145);}
  predicateLabel(a){if(a.op==='and'||a.op==='or')return a.args.map(p=>this.predicateLabel(p)).join(a.op==='and'?' ∧ ':' ∨ ');if(a.op==='not')return `¬ (${this.predicateLabel(a.arg)})`;const name=this.snapshot.columns?.find(c=>c.id===a.field||c.name===a.field)?.name??a.field;if(a.op==='between')return `${name} ∈ [${fmt(a.min,2)}, ${fmt(a.max,2)}]`;return `${name} ${t(a.op)} ${a.values?.join(', ')??a.value??''}`;}
  restoreView(view){this.channels=view?.channels??{};if(view?.config)this.config=view.config;if(CHARTS.includes(view?.chartType))this.chartType=view.chartType;if(['dataPreview','statistics','pandas'].includes(view?.tab))this.tab=view.tab;if([20,50,100].includes(view?.pageSize))this.pageSize=view.pageSize;if(['zh-CN','en-US'].includes(view?.locale))setLocale(view.locale);this.offset=0;}
  drawPreview(){if(!this.preview)return;const host=$('[data-operation-feedback]');drawFeedback(host,this.preview,{onField:ref=>this.configureMissing(ref)});if(this.preview.spec.type==='dedup'&&host){const button=document.createElement('button');button.className='text-button';button.textContent=t('component034');host.append(button);button.onclick=()=>this.safe(async()=>{const d=await this.worker.call('duplicates',this.pendingOperation.spec.params);this.dialog(t('dedup'),`<p>${t('affected')}: ${d.count} · ${t('component035')}</p>${this.tableHTML(d.records,d.columns,false)}`);});}}
  click(event){const button=event.target.closest('button');if(!button)return;const d=button.dataset;if(button.disabled)return;if(this.busyCount&&d.action!=='cancel')return;
    this.safe(async()=>{
      if(d.action){switch(d.action){
        case 'chart-gallery':this.galleryDialog();return;
        case 'locale':$('#toast')?.remove();clearTimeout(this.previewTimer);this.previewVersion++;this.preserveDraft();setLocale(getLocale()==='zh-CN'?'en-US':'zh-CN');this.render();return;
        case 'go-nba':this.goto('nba');return;case 'go-studio':this.goto('studio');return;
        case 'upload':this.filePicker('.csv,.tsv,.json,.xlsx',file=>this.openImport(file));return;
        case 'add-nba':this.nbaDialog();return;
        case 'about':this.aboutDialog();return;
        case 'clear-selection':this.channels={};this.offset=0;await this.analyze();return;
        case 'apply-selection':if(this.selection())await this.mutate('commit',{spec:{type:'filter',params:{predicate:this.selection()}}});return;
        case 'preview':await this.requestPreview(false);return;
        case 'commit':if(!this.pendingOperation||!this.preview)return;await this.mutate('commit',this.pendingOperation);this.toast(t('done'));return;
        case 'undo':case 'redo':this.draft=null;await this.mutate(d.action);return;
        case 'prev-page':this.offset=Math.max(0,this.offset-this.pageSize);await this.analyze();return;
        case 'next-page':this.offset+=this.pageSize;await this.analyze();return;
        case 'head':this.offset=0;await this.analyze();return;
        case 'tail':this.offset=Math.max(0,(this.snapshot.rows??0)-this.pageSize);await this.analyze();return;
        case 'chart-svg':case 'chart-png':await this.export(d.action.slice(6));return;
        case 'send-studio':if(this.selection())await this.mutate('commit',{spec:{type:'filter',params:{predicate:this.selection()}}});this.draft=null;this.goto('studio');return;
        case 'cancel':await this.worker.cancel();this.channels={};await this.analyze();this.toast(errorText({code:'CANCELLED'}));return;
        case 'restore-flow':this.filePicker('.json',file=>this.restoreFile(file));return;
        case 'save-local':await localProject('put',{...await this.worker.call('checkpoint'),view:this.view()});this.toast(t('saved'));return;
        case 'restore-local':{const data=await localProject('get');if(!data)throw new Error('NO_LOCAL_PROJECT');await this.worker.call('recover',data);this.loaded=new Set(data.flow.sources.filter(s=>s.sourceId.startsWith('nba_')).map(s=>s.sourceId.slice(4)));this.restoreView(data.view);this.draft=null;await this.worker.retain();this.goto('studio');await this.analyze();this.toast(t('restored'));return;}
        case 'clear-local':await localProject('delete');await localProject('delete',null,'navigation');this.toast(t('component036'));return;
      }}
      if(d.nbaGuide){await this.startNBAGuide(d.nbaGuide);return;}if(d.originalData){await this.worker.call('select',{id:'source:example_nba_games'});this.channels={};this.draft=null;this.config={x:'pts',y:'ast',category:'team',date:'game_date',metric:'pts',aggregate:'mean'};this.routeURL(true,'source:example_nba_games');await this.analyze();return;}if(d.auditData){download(await(await fetch(`${BASE}data/examples/nba-missing-audit.json`)).json(),'nba-missing-audit.json');return;}if(d.operationStart){const state=await this.worker.call('snapshot'),columns=state.columns??[],num=columns.find(isNumericColumn),category=columns.find(c=>!isNumericColumn(c)&&c.semantic!=='key'&&!['date','datetime'].includes(c.type));let values;if(d.operationStart==='group'&&num&&category)values={keys:[category.id],metric0:num.id,fn0:'mean',as0:'mean_value'};if(d.operationStart==='fillna'&&num)values={field:num.id,method:'median'};this.draft={type:d.operationStart,values};this.preview=null;this.goto('studio');return;}
      if(d.node){this.channels={};this.offset=0;this.draft=null;this.preview=null;await this.worker.call('select',{id:d.node});this.routeURL(true,d.node);await this.analyze();await this.worker.retain();const step=$('.applied-step');if(step)step.open=true;return;}
      if(d.removeSource){await this.mutate('removeSource',{id:d.removeSource});this.loaded.delete(d.removeSource.replace('nba_',''));return;}
      if(d.deleteNode){await this.mutate('removeNode',{id:d.deleteNode});return;}
      if(d.edit){this.editDialog(d.edit);return;}
      if(d.drill){await this.drillDialog(d.drill);return;}
      if(d.changeType){this.typeDialog(d.changeType);return;}if(d.field){this.profileDialog(d.field);return;}if(d.clearChannel){delete this.channels[d.clearChannel];this.offset=0;await this.analyze();return;}
      if(d.sort){if(this.selection()){this.toast(t('applyFirst'),true);return;}const ascending=this.lastSort?.field===d.sort?!this.lastSort.ascending:true;this.lastSort={field:d.sort,ascending};await this.mutate('commit',{spec:{type:'sort',params:{by:[d.sort],ascending}}});return;}
      if(d.tab){this.tab=d.tab;this.preserveDraft();this.render();return;}
      if(d.export){await this.export(d.export);return;}
      if(d.nbaTab){this.nbaTab=d.nbaTab;this.nbaValues=[];await this.activateNBA();this.routeURL(true);return;}
      if(d.useChart){this.chartType=d.useChart;this.goto('studio');return;}
      if(d.question){if(d.question==='upload'){this.filePicker('.csv,.tsv,.json,.xlsx',file=>this.openImport(file));return;}this.nbaTab=d.question==='court'?'courtTab':'playerTab';this.goto('nba');return;}
      if(d.leader){this.nbaTab='playerTab';this.pendingNBASelection={entity:{op:'eq',field:'player_name',value:d.leader}};this.goto('nba');return;}
    });
  }
  change(event){const el=event.target;if(this.busyCount)return;
    if(el.dataset.config){this.safe(async()=>{this.preserveDraft();this.config[el.dataset.config]=el.multiple?[...el.selectedOptions].map(o=>o.value):el.type==='number'?Number(el.value):el.value;this.offset=0;await this.analyze();});return;}
    if(el.id==='show-diff'){this.showDiff=el.checked;this.updateDiff();if(this.showDiff&&!this.preview)this.safe(()=>this.loadStepFeedback(this.queryVersion));return;}
    if(el.id==='chart-type'){this.preserveDraft();this.chartType=el.value;if(this.chartType==='court')this.safe(()=>this.analyze());else this.render();return;}
    if(el.id==='page-size'){this.safe(async()=>{this.pageSize=Number(el.value);this.offset=0;await this.analyze();});return;}
    if(el.id==='nba-entity'){this.safe(async()=>{this.channels.entity=el.value?{op:'eq',field:this.nbaTab==='courtTab'?'player_id':this.nbaTab==='playerTab'?'player_name':'team_abbr',value:el.value}:null;this.offset=0;await this.analyze();});return;}
    if(el.id==='nba-metric'){this.safe(async()=>{this.config.metric=el.value;if(this.chartType!=='court')this.config.x=el.value;await this.analyze();});}
  }
  filePicker(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>input.files[0]&&this.safe(()=>callback(input.files[0]));input.click();}
  dialog(title,body,bind){$('#datalab-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='datalab-dialog';dialog.innerHTML=`<div class="dialog-heading"><h2>${esc(title)}</h2><button class="icon-button" data-close aria-label="${t('close')}">×</button></div><div class="dialog-content">${body}</div>`;document.body.append(dialog);$('[data-close]',dialog).onclick=()=>dialog.close();dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});dialog.showModal();bind?.(dialog);return dialog;}
  async openImport(file){this.importData=await readUpload(file);this.importTypes=null;await this.importDialog();}
  async importDialog(){const data=this.importData;data.sheetIndex??=0;const text=data.sheets?.[data.sheetIndex].text??data.text,options={format:data.format,fileName:data.fileName,...data.options,types:this.importTypes??undefined};const prepared=await this.worker.call('prepare',{text,options});this.importTypes=Object.fromEntries(prepared.schema.map(c=>[c.name,c.type]));
    this.dialog(t('importTitle'),`<p>${t('importNote')}</p><div class="import-file-label">${icon('database')}<strong>${esc(data.fileName)}</strong><span>${fmt(prepared.rowCount,0)} ${t('rows')} · ${prepared.schema.length} ${t('columns')}</span></div>${data.sheets?`<label>${t('sheet')}<select id="import-sheet">${data.sheets.map((s,i)=>`<option value="${i}" ${i===data.sheetIndex?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>`:''}<div class="import-options">${data.format!=='json'?`<label>${t('delimiter')}<select id="import-delimiter">${[[',',t('component037')],['\t',t('component038')],[';',t('component039')],['|','|']].map(([v,name])=>`<option value="${esc(v)}" ${v===(data.options?.delimiter??(data.format==='tsv'?'\t':','))?'selected':''}>${name}</option>`).join('')}</select></label>`:''}<label>${t('nullTokens')}<input id="null-tokens" value="${esc(data.options?.nullTokens?.join(',')??'')}"></label></div><div class="import-types">${prepared.schema.map(c=>`<label>${esc(c.name)}<select data-type-field="${esc(c.name)}">${['string','category','number','integer','boolean','date','datetime'].map(type=>`<option value="${type}" ${c.type===type?'selected':''}>${t(type==='date'?'dateType':type==='category'?'categoryType':type)}</option>`).join('')}</select></label>`).join('')}</div>${prepared.errors.length?`<div class="inline-error" role="alert">${t('invalidWarning')} (${prepared.errors.length})<details><summary>${t('invalid')}</summary><pre>${esc(JSON.stringify(prepared.errors.slice(0,8),null,2))}</pre></details></div>`:''}${this.tableHTML(prepared.preview,prepared.schema,false)}<label class="check"><input id="import-coerce" type="checkbox">${t('coerce')}</label><p class="hint">${t('localPrivacy')} · ${t('importFormat')}</p><div class="dialog-actions"><button id="confirm-import" class="button primary">${t('confirmImport')}${icon()}</button></div>`,dialog=>{
      $$('[data-type-field]',dialog).forEach(el=>el.onchange=()=>this.safe(async()=>{this.importTypes[el.dataset.typeField]=el.value;await this.importDialog();}));
      $('#import-sheet',dialog)?.addEventListener('change',e=>this.safe(async()=>{data.sheetIndex=+e.target.value;this.importTypes=null;await this.importDialog();}));
      const updateParse=()=>{data.options={delimiter:$('#import-delimiter',dialog)?.value,nullTokens:$('#null-tokens',dialog).value.split(',').map(v=>v.trim()).filter(Boolean)};this.importTypes=null;this.safe(()=>this.importDialog());};
      $('#import-delimiter',dialog)?.addEventListener('change',updateParse);$('#null-tokens',dialog).onchange=updateParse;
      $('#confirm-import',dialog).onclick=()=>this.safe(async()=>{const opts={...options,types:this.importTypes,errors:$('#import-coerce',dialog).checked?'coerce':'raise'};await this.worker.call('import',{text,options:opts});await this.worker.retain();this.channels={};this.config={correlation:true,aggregate:'mean'};this.draft=null;this.offset=0;this.tab='dataPreview';this.preview=null;dialog.close();this.route='studio';location.hash='/studio';await this.analyze();});
    });
  }
  async restoreFile(file){if(file.size>50*1024*1024)throw new Error('FILE_LIMIT');const data=JSON.parse(await file.text());if(data.sources?.[0]?.records){await this.worker.call('recover',data);this.loaded=new Set(data.flow.sources.filter(s=>s.sourceId.startsWith('nba_')).map(s=>s.sourceId.slice(4)));}else{const missing=data.sources?.filter(s=>s.sourceId.startsWith('nba_')&&!this.loaded.has(s.sourceId.slice(4))).map(s=>s.sourceId.slice(4))??[];if(missing.length)await this.loadNBA(missing);await this.worker.call('restore',{flow:data});}this.restoreView(data.view);this.draft=null;await this.worker.retain();this.goto('studio');await this.analyze();this.toast(t('restored'));}
  nbaDialog(){this.dialog(t('builtIns'),`<div class="example-choices">${Object.entries(examples).map(([id,meta])=>`<button class="source-choice" data-example="${id}"><span>${local(meta.name)}<small>${local(meta.note)}</small></span>↗</button>`).join('')}</div><details><summary>${t('rawNBA')}</summary><div class="nba-source-list">${this.manifest.tables.map(table=>`<button class="source-choice" data-source="${table.id}"><span>${local(NBA_LABELS[table.id])}<small>${table.rows} ${t('rows')}</small></span>↗</button>`).join('')}</div></details>`,dialog=>{
    $$('[data-example]',dialog).forEach(el=>el.onclick=()=>this.safe(async()=>{await this.loadExamples([el.dataset.example]);this.channels={};this.draft=null;this.offset=0;this.config={aggregate:'mean',correlation:true};this.chartType='scatter';this.tab='dataPreview';await this.worker.call('select',{id:`source:example_${el.dataset.example}`});this.routeURL(true,`source:example_${el.dataset.example}`);dialog.close();await this.analyze();await this.worker.retain();}));
    $$('[data-source]',dialog).forEach(el=>el.onclick=()=>this.safe(async()=>{await this.loadNBA([el.dataset.source]);this.channels={};this.draft=null;this.offset=0;await this.worker.call('select',{id:`source:nba_${el.dataset.source}`});this.config={aggregate:'mean',correlation:true};this.chartType=el.dataset.source==='shots'?'court':'scatter';dialog.close();await this.analyze();await this.worker.retain();}));
  });}
  aboutDialog(){this.dialog(t('about'),`<p>${t('builtIns')}: ${Object.values(examples).map(meta=>local(meta.name)).join(' · ')}</p><p>${local(examples.nba_players.note)}</p><p>${local(examples.titanic.note)} <a href="https://github.com/mwaskom/seaborn-data/blob/a29a0141d20e156043ec257a64c8de3b3a03fd6e/titanic.csv" target="_blank" rel="noreferrer">seaborn / Kaggle ↗</a></p><div class="about-grid"><div><span class="eyebrow">${t('component040')}</span><h3>${t('dataWindow')}</h3><p>${t('snapshotNote')}</p><p>${t('sourceAttribution')}</p><a href="https://github.com/sportsdataverse/sportsdataverse-data" target="_blank" rel="noreferrer">${t('component041')} ↗</a><p>${t('coordinateNote')}</p><a href="https://sdvplotr.sportsdataverse.org/reference/sdv_court_coords.html" target="_blank" rel="noreferrer">${t('component042')} ↗</a><p>${t('component043')}</p></div><div><h3>${t('localPrivacy')}</h3><p>${t('offlineNote')}</p><p>${t('localSaveNote')}</p><h3>${t('component044')}</h3><p>${t('component045')}</p><div class="source-links"><a href="https://github.com/sportsdataverse/sportsdataverse-data/blob/c30618f5f439abc8275f0a9bea30892a598890b8/README.md" target="_blank" rel="noreferrer">${t('component046')} ↗</a><a href="https://www.nba.com/termsofuse" target="_blank" rel="noreferrer">${t('component047')} ↗</a></div><p>${t('licenseNote')}</p><button class="button secondary" id="manifest-download">${t('component048')}${icon('download')}</button></div></div>`,dialog=>$('#manifest-download',dialog).onclick=()=>download(this.manifest,'nba-source-manifest.json'));}
  profileDialog(ref){const c=this.snapshot.profile?.columns.find(c=>c.id===ref);if(!c)return;this.dialog(`${t('profileField')} · ${c.name}`,`<div class="field-profile-header"><span class="pill">${c.type}</span><strong>${fmt(c.count,0)} ${t('valid')}</strong><span>${fmt(c.missing,0)} ${t('missing')} (${fmt(c.missingRate===null?null:c.missingRate*100,1)}%)</span><span>${fmt(c.unique,0)} ${t('unique')}</span></div>${c.values?`<h3>${t('topValues')} · ${t('component049')}</h3><div class="frequency-list">${c.values.slice(0,30).map(v=>`<div><span>${esc(v.value??t('na'))}</span><div class="frequency-bar" style="--width:${v.proportion*100}%"></div><strong>${fmt(v.count,0)}</strong><small>${fmt(v.proportion*100,1)}%</small></div>`).join('')}</div>`:`<div class="field-stat-grid">${['mean','var','std','min','q1','median','q3','max'].map(key=>`<div><small>${t(key)}</small><strong>${fmt(c[key],4)}</strong></div>`).join('')}</div>`}${!c.values?`<div class="quantile-query"><label>${t('component050')}<input type="number" id="quantile-q" min="0" max="1" step=".01" value=".25"></label><button id="query-quantile" class="button secondary small">${t('component051')}</button><strong id="quantile-result">${fmt(c.q1,4)}</strong></div>`:''}<div class="dialog-actions"><button id="field-clean" class="button secondary">${t('fillna')}</button><button id="field-frequency" class="button secondary">${t('resultCSV')}${icon('download')}</button></div>`,dialog=>{if($('#query-quantile',dialog))$('#query-quantile',dialog).onclick=()=>this.safe(async()=>{$('#quantile-result',dialog).textContent=fmt(await this.worker.call('quantile',{field:ref,q:Number($('#quantile-q',dialog).value),selection:this.selection()}),5);});$('#field-clean',dialog).onclick=()=>{dialog.close();if(this.route!=='studio'){this.draft={type:'fillna',values:{field:ref}};this.goto('studio');}else{this.form.type='fillna';this.form.saved=null;this.form.draw();this.form.setField(ref);this.schedulePreview();this.form.host.scrollIntoView({block:'center',behavior:'smooth'});}};$('#field-frequency',dialog).onclick=()=>this.safe(async()=>download(asCSV(await this.worker.call('analysisExport',{kind:'frequencies',fields:[ref],selection:this.selection()})),`${c.name}-frequencies.csv`,'text/csv'));});}
  editDialog(id){const node=this.snapshot.nodes.find(n=>n.id===id);if(!node)return;this.dialog(`${t('edit')} · ${operationLabel(node.spec.type,node.spec.params)}`,`<p>${t('component052')}</p><textarea id="edit-spec" class="json-editor" rows="14" spellcheck="false">${esc(JSON.stringify(node.spec,null,2))}</textarea><div id="edit-report"></div><div class="dialog-actions"><button id="preview-edit" class="button secondary">${t('preview')}</button><button id="apply-edit" class="button primary" disabled>${t('apply')}</button></div>`,dialog=>{let spec,revision=0;$('#edit-spec',dialog).oninput=()=>{revision++;$('#apply-edit',dialog).disabled=true;$('#edit-report',dialog).innerHTML='';};$('#preview-edit',dialog).onclick=()=>this.safe(async()=>{const current=++revision,next=JSON.parse($('#edit-spec',dialog).value),preview=await this.worker.call('preview',{spec:next,inputs:node.inputs});if(current!==revision)return;spec=next;$('#edit-report',dialog).innerHTML=`<p>${t('pendingPreview')} · ${esc(operationLabel(spec.type,spec.params))}</p><p>${t('rows')}: ${preview.report.before.rows} → ${preview.rows} · ${t('columns')}: ${preview.report.before.columns} → ${preview.columns.length}</p><div data-edit-feedback></div><details><summary>${t('equivalentCode')}</summary><pre>${esc(preview.pandas?.code??'')}</pre></details>`;drawFeedback($('[data-edit-feedback]',dialog),preview);$('#apply-edit',dialog).disabled=false;});$('#apply-edit',dialog).onclick=()=>this.safe(async()=>{await this.mutate('edit',{id,spec});dialog.close();this.toast(t('done'));});});}
  async drillDialog(id){const node=this.snapshot.nodes.find(n=>n.id===id);const records=await this.worker.call('analysisExport',{id,kind:'rows'}),table=this.snapshot.tables.find(t=>t.id===id),input=this.snapshot.tables.find(t=>t.id===node.inputs[0]),keys=node.spec.params.keys??node.spec.params.index;const keyRefs=Array.isArray(keys)?keys:[keys],keyCols=keyRefs.map(ref=>input.columns.find(c=>c.id===ref||c.name===ref));
    this.dialog(t('component025'),`<p>${t('component053')}</p><label>${t('groupKeys')}<select id="drill-row">${records.map((r,i)=>`<option value="${i}">${esc(keyCols.map(c=>`${c.name}: ${r[c.name]??t('na')}`).join(' / '))}</option>`).join('')}</select></label>${node.spec.type.startsWith('pivot')?`<label>${t('columnKeys')}<select id="drill-column"><option value="">${t('component054')}</option>${table.columns.filter(c=>c.pivotValues).map(c=>`<option value="${esc(c.id)}">${esc(c.pivotValues.join(' / '))}</option>`).join('')}</select></label>`:''}<div class="dialog-actions"><button id="drill-apply" class="button primary">${t('goStudio')}${icon()}</button></div>`,dialog=>{$('#drill-apply',dialog).disabled=!records.length;$('#drill-apply',dialog).onclick=()=>this.safe(async()=>{const r=records[+$('#drill-row',dialog).value],args=keyCols.map(c=>r[c.name]===null?{op:'isMissing',field:c.id}:{op:'eq',field:c.id,value:r[c.name]});const selected=$('#drill-column',dialog)?.value;if(selected){const values=table.columns.find(c=>c.id===selected).pivotValues;const refs=Array.isArray(node.spec.params.columns)?node.spec.params.columns:[node.spec.params.columns];refs.forEach((ref,i)=>args.push(values[i]===null?{op:'isMissing',field:ref}:{op:'eq',field:ref,value:values[i]}));}await this.mutate('commit',{spec:{type:'filter',params:{predicate:and(args)}},inputs:node.inputs.slice(0,1)});dialog.close();this.goto('studio');});});
  }
  async export(kind){if(!this.snapshot.activeId)throw new Error('SELECT_FIRST');const name=`datalab-${this.snapshot.activeId.replace(':','-')}`;
    if(['svg','png'].includes(kind)){const host=$('#main-chart');if(!host)throw new Error('NO_CHART');download(await exportChart(host,kind,`${t(this.chartType)} · ${this.name(this.snapshot.activeId)}`,`${this.snapshot.rows} ${t('rows')} · ${this.sourceCaption()||t('currentData')} · ${new Date().toISOString().slice(0,10)}`),`${name}.${kind}`);}
    else if(kind==='csv'||kind==='selectionCSV')download(await this.worker.call('csv',{selection:kind==='selectionCSV'?this.selection():null}),`${name}${kind==='selectionCSV'?'-selection':''}.csv`,'text/csv');
    else if(kind==='flow')download({...await this.worker.call('flow'),view:this.view()},`${name}-flow.json`);
    else if(kind==='project')download({...await this.worker.call('checkpoint'),view:this.view()},`${name}-project.json`);
    else if(kind==='python')download(await this.worker.call('pandas'),`${name}.py`,'text/x-python');
    else{const fields=this.snapshot.columns.filter(c=>isNumericColumn(c)).map(c=>c.id).slice(0,12);const records=await this.worker.call('analysisExport',{kind:this.chartType==='correlation'?'correlation':'rows',fields,selection:this.selection()});download(kind==='resultCSV'?asCSV(records):{dataset:this.snapshot.activeId,selection:this.selection(),profile:this.snapshot.profile,provenance:this.snapshot.provenance,sources:this.activeSources(),nbaManifest:this.activeSources().some(s=>s.sourceId.startsWith('nba_'))?this.manifest:undefined,records},`${name}-analysis.${kind==='resultCSV'?'csv':'json'}`,kind==='resultCSV'?'text/csv':'application/json');}
    this.toast(t('downloaded'));
  }
}
